  boardId: string;
  level: number;
  tx: number;
  ty: number;
  state: Uint8Array;
  usedAt: number;
};

type PendingRecord = {
  boardId: string;
  level: number;
  tx: number;
  ty: number;
  update: Uint8Array;
};

