  objects: { key: TileKey; value: TileRecord };
  tiles: {
    key: [string, number, number, number];
    value: TileStateRecord;
    indexes: { usedAt: number };
  };
  pending: { key: number; value: PendingRecord; indexes: { boardId: string } };
}

