}

export type TileState = { tile: Tile; state: Uint8Array };

export type QueuedUpdate = { id: number; tile: Tile; update: Uint8Array };

export type TileCache = {
  load(ranges: readonly LevelRange[]): Promise<TileState[]>;
  save(tile: Tile, state: Uint8Array): Promise<void>;
  enqueue(tile: Tile, update: Uint8Array): Promise<void>;
  drain(): Promise<QueuedUpdate[]>;
  ack(ids: readonly number[]): Promise<void>;
  close(): void;
};

export type TileCacheOptions = { name?: string; cap?: number };

export const DEFAULT_TILE_CAP = 2048;

let lastUsedAt = 0;
const nextUsedAt = (): number => {
  lastUsedAt = Math.max(Date.now(), lastUsedAt + 1);
  return lastUsedAt;
};

const inRange = (range: LevelRange, ty: number): boolean => ty >= range.minTy && ty <= range.maxTy;

export async function openTileCache(
  boardId: string,
  { name = DB_NAME, cap = DEFAULT_TILE_CAP }: TileCacheOptions = {},
): Promise<TileCache> {
  const db = await openStallionDB(name);

  const load = async (ranges: readonly LevelRange[]): Promise<TileState[]> => {
    const tx = db.transaction("tiles", "readonly");
    const results = await Promise.all(
      ranges.map(async (range) => {
        const records = await tx.store.getAll(
          IDBKeyRange.bound(
            [boardId, range.level, range.minTx, Number.NEGATIVE_INFINITY],
            [boardId, range.level, range.maxTx, Number.POSITIVE_INFINITY],
          ),
        );
        return records
          .filter((record) => inRange(range, record.ty))
          .map((record) => ({
            tile: { level: record.level, tx: record.tx, ty: record.ty },
            state: record.state,
          }));
      }),
    );
    await tx.done;
    return results.flat();
  };

  const save = async (tile: Tile, state: Uint8Array): Promise<void> => {
    const tx = db.transaction("tiles", "readwrite");
    await tx.store.put({ boardId, ...tile, state, usedAt: nextUsedAt() });
    let excess = (await tx.store.count()) - cap;
    let cursor = excess > 0 ? await tx.store.index("usedAt").openCursor() : null;
    while (cursor && excess > 0) {
      await cursor.delete();
      excess--;
      cursor = await cursor.continue();
    }
    await tx.done;
  };

  const enqueue = async (tile: Tile, update: Uint8Array): Promise<void> => {
    await db.add("pending", { boardId, ...tile, update });
  };

  const drain = async (): Promise<QueuedUpdate[]> => {
    const queued: QueuedUpdate[] = [];
    const tx = db.transaction("pending", "readonly");
    let cursor = await tx.store.index("boardId").openCursor(boardId);
    while (cursor) {
      const { level, tx: column, ty, update } = cursor.value;
      queued.push({ id: cursor.primaryKey, tile: { level, tx: column, ty }, update });
      cursor = await cursor.continue();
    }
    await tx.done;
    return queued;
  };
  };
  return { objects, map, notify };
};

const debounced = (run: (viewport: BBox, zoom: number) => void) => {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return {
    call(viewport: BBox, zoom: number): void {
      clearTimeout(timer);
      timer = setTimeout(() => run(viewport, zoom), VIEW_DEBOUNCE_MS);
    },
    cancel(): void {
      clearTimeout(timer);
    },
  };
};

export function openLocalSource(boardId: string, onError: (message: string) => void): BoardSource {
  const { objects, map, notify } = liveObjects();
  const removed = new Set<string>();
  const storeReady: Promise<BoardStore> = openBoardStore(boardId);
  const fail = (action: string) => (error: unknown) => onError(`${action}: ${errorMessage(error)}`);
  storeReady.catch(fail("Could not open the local board storage"));

  const setView = debounced((viewport, zoom) => {
    const tiles = viewTiles(viewport, zoom);
    storeReady
      .then((store) => store.query([...tiles.live, ...tiles.snapshot]))
      .then((found) => {
        const changed = new Set<string>();
        for (const stored of found) {
          const { objectId } = stored.object;
          if (map.has(objectId) || removed.has(objectId)) continue;
          map.set(objectId, stored);
          changed.add(objectId);
        }
        notify(changed);
      })
      .catch(fail("Could not load the board from local storage"));
  });

  return {
    view: setView.call,
    commit(stored) {
      map.set(stored.object.objectId, stored);
      notify(new Set([stored.object.objectId]));
      storeReady
        .then((store) => store.put(stored))
        .catch(fail("Could not save the stroke to local storage"));
    },
    erase(objectId) {
      const stored = map.get(objectId);
      if (!stored) return;
      removed.add(objectId);
      map.delete(objectId);
      notify(new Set([objectId]));
      storeReady
        .then((store) => store.remove(objectId, stored.tile))
        .catch(fail("Could not delete the stroke from local storage"));
    },
    objects,
    awareness: undefined,
    async close() {
      setView.cancel();
      await storeReady.then(
        (store) => store.close(),
        () => undefined,
      );
    },
  };
}

export function openSyncSource(url: string, options: SourceOptions): BoardSource {
  const online = () => globalThis.navigator?.onLine !== false;
  const board = options.openBoard(url, options.boardId, {
    onStatus: (status) => options.onConnection(connectionFor(status, online())),
    onError: ({ tileKey, reason }) =>
      options.onError(`Sync failed${tileKey ? ` on tile ${tileKey}` : ""}: ${reason}`),
  });
  options.onConnection(connectionFor(board.status, online()));
  const setView = debounced((viewport, zoom) => board.setView(viewport, zoom));
  return {
    view: setView.call,
    commit: (stored) => board.put(stored),
    erase: (objectId) => board.remove(objectId),
    objects: board.objects,
    awareness: board.awareness,
    close() {
      setView.cancel();
      return board.close();
    },
  };
}

export function openSource(options: SourceOptions): BoardSource {
  if (!options.url) {
    options.onConnection("LocalOnly");
    return openLocalSource(options.boardId, options.onError);
  }
  try {
    return openSyncSource(options.url, options);
  } catch (error) {
    options.onError(
      `Could not connect to ${options.url} (${errorMessage(error)}), working local only`,
    );
    options.onConnection("LocalOnly");
    return openLocalSource(options.boardId, options.onError);
  }
