    () =>
      new Promise((resolve, reject) => {
        const request = indexedDB.open("stallion");
        request.onerror = () => reject(request.error);
        request.onsuccess = () => {
          const db = request.result;
          const stores = [...db.objectStoreNames];
          if (stores.length === 0) {
            db.close();
            resolve({});
